"""Bounded character-Trie-aware DataFrame column permutation search."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Reorder columns and rows to maximize exact serialized-prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional input frame and the most recent row permutations."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Serialize one scalar, mapping scalar missing values to the empty string."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute an exact common-prefix length using binary-search slicing."""
        if left == right:
            return len(left)
        lo, hi = 0, min(len(left), len(right))
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if left[:mid] == right[:mid]:
                lo = mid
            else:
                hi = mid - 1
        return lo

    @classmethod
    def _score(cls, strings) -> int:
        """Compute exact sorted-adjacent character-Trie reuse."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(
                previous, current
            )
            previous = current
        return total

    @staticmethod
    def _positions(columns):
        """Map stringified column labels to their source positions."""
        positions = {}
        for i, name in enumerate(columns):
            positions.setdefault(str(name), []).append(i)
        return positions

    @classmethod
    def _blocks(cls, width, columns, requested):
        """Build disjoint ordered merge blocks with union-find."""
        parent = list(range(width))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        positions = cls._positions(columns)
        for pair in requested or []:
            if len(pair) != 2:
                continue
            a = positions.get(str(pair[0]), [])
            b = positions.get(str(pair[1]), [])
            if len(a) == 1 and len(b) == 1:
                ra, rb = find(a[0]), find(b[0])
                if ra != rb:
                    parent[rb] = ra

        groups = {}
        for i in range(width):
            groups.setdefault(find(i), []).append(i)
        return sorted((sorted(v) for v in groups.values()), key=lambda x: x[0])

    @classmethod
    def _repair(cls, width, preference, columns, dependencies, blocks):
        """Return a preference-biased topological order respecting all constraints."""
        positions = cls._positions(columns)
        edges = []
        seen = set()

        def add(a, b):
            if a != b and (a, b) not in seen:
                seen.add((a, b))
                edges.append((a, b))

        for pair in dependencies or []:
            if len(pair) != 2:
                continue
            a = positions.get(str(pair[0]), [])
            b = positions.get(str(pair[1]), [])
            if len(a) == 1 and len(b) == 1:
                add(a[0], b[0])

        for block in blocks:
            for a, b in zip(block, block[1:]):
                add(a, b)

        outgoing = [[] for _ in range(width)]
        indegree = [0] * width
        for a, b in edges:
            outgoing[a].append(b)
            indegree[b] += 1

        rank = {value: i for i, value in enumerate(preference)}
        heap = [
            (rank.get(i, width + i), i)
            for i in range(width)
            if indegree[i] == 0
        ]
        heapq.heapify(heap)

        result = []
        while heap:
            _, node = heapq.heappop(heap)
            result.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank.get(nxt, width + nxt), nxt))

        return result if len(result) == width else list(preference)

    @staticmethod
    def _stats(text):
        """Compute length-weighted repetition statistics for every column."""
        result = []
        rows, width = text.shape
        for col in range(width):
            counts = {}
            for value in text[:, col]:
                counts[value] = counts.get(value, 0) + 1
            pair = repeat = mass = 0
            for value, count in counts.items():
                length = len(value)
                pair += length * count * (count - 1)
                repeat += length * max(0, count - 1)
                mass += length * count
            result.append((pair, repeat, mass))
        return result

    @classmethod
    def _beam_orders(cls, text, stats, blocks):
        """Generate a small deterministic set of block-level preferences."""
        if len(blocks) <= 1:
            return [sum(blocks, [])]

        mass = [sum(stats[col][0] for col in block) for block in blocks]
        active = sorted(
            range(len(blocks)),
            key=lambda i: (-mass[i], blocks[i][0]),
        )[:24]

        affinity = {}
        for a in active:
            for b in active:
                if a == b:
                    continue
                value = 0
                for left in blocks[a][:2]:
                    for right in blocks[b][:2]:
                        groups = {}
                        for row in range(text.shape[0]):
                            groups.setdefault(text[row, left], []).append(row)
                        for members in groups.values():
                            if len(members) < 2:
                                continue
                            counts = {}
                            for row in members:
                                item = text[row, right]
                                counts[item] = counts.get(item, 0) + 1
                            value += sum(
                                len(item) * count * (count - 1)
                                for item, count in counts.items()
                            )
                affinity[a, b] = value

        beam = [
            ((seed,), frozenset(active) - {seed}, 0)
            for seed in active
        ]
        for _ in range(max(0, len(active) - 1)):
            expanded = []
            for path, remaining, value in beam:
                if not remaining:
                    expanded.append((path, remaining, value))
                    continue
                for nxt in remaining:
                    expanded.append(
                        (
                            path + (nxt,),
                            remaining - {nxt},
                            value + affinity.get((path[-1], nxt), 0),
                        )
                    )
            expanded.sort(key=lambda item: (-item[2], item[0]))
            beam = expanded[:4]

        answers = []
        seen = set()
        for path, _, _ in beam:
            tail = sorted(
                (i for i in range(len(blocks)) if i not in path),
                key=lambda i: (-mass[i], blocks[i][0]),
            )
            flat = tuple(
                col
                for block_index in tuple(path) + tuple(tail)
                for col in blocks[block_index]
            )
            if flat not in seen:
                seen.add(flat)
                answers.append(list(flat))
            if len(answers) == 2:
                break
        return answers or [sum(blocks, [])]

    @staticmethod
    def _serialize(text, order):
        """Serialize each row under one source-column permutation."""
        return [
            "".join(text[row, col] for col in order)
            for row in range(text.shape[0])
        ]

    @classmethod
    def _refine_reversals(
        cls,
        text,
        stats,
        blocks,
        columns,
        dependencies,
        incumbent,
        incumbent_serialized,
        incumbent_score,
    ):
        """Try at most twelve exact-scored contiguous block-segment reversals."""
        if len(blocks) > 24 or sum(len(v) for v in text.flat) > 2_000_000:
            return incumbent, incumbent_serialized, incumbent_score

        block_of = {}
        for i, block in enumerate(blocks):
            for col in block:
                block_of[col] = i

        sequence = [block_of[col] for col in incumbent]
        if len(sequence) != len(blocks) or len(set(sequence)) != len(blocks):
            return incumbent, incumbent_serialized, incumbent_score

        ranked = sorted(
            range(len(blocks)),
            key=lambda i: (-stats[blocks[i][0]][0], blocks[i][0]),
        )
        endpoints = set()
        for index in ranked[:6]:
            endpoints.add(index)
            if index:
                endpoints.add(index - 1)
            if index + 1 < len(blocks):
                endpoints.add(index + 1)

        positions = {block: i for i, block in enumerate(sequence)}
        candidates = []
        for block in sorted(endpoints):
            p = positions[block]
            for other in sorted(endpoints):
                q = positions[other]
                if p < q:
                    candidates.append((q - p, p, q))
        candidates.sort(key=lambda x: (x[0], x[1], x[2]))

        tested = 0
        for _, left, right in candidates:
            if tested >= 12:
                break
            tested += 1
            proposed_blocks = (
                sequence[:left]
                + list(reversed(sequence[left : right + 1]))
                + sequence[right + 1 :]
            )
            preference = [
                col
                for block_index in proposed_blocks
                for col in blocks[block_index]
            ]
            repaired = cls._repair(
                len(columns), preference, columns, dependencies, blocks
            )
            repaired_blocks = [block_of[col] for col in repaired]
            if repaired_blocks != proposed_blocks:
                continue

            serialized = cls._serialize(text, repaired)
            score = cls._score(serialized)
            if score > incumbent_score:
                incumbent = repaired
                incumbent_serialized = serialized
                incumbent_score = score
                sequence = proposed_blocks
                positions = {block: i for i, block in enumerate(sequence)}

        return incumbent, incumbent_serialized, incumbent_score

    @staticmethod
    def _materialize(df, source, order, serialized):
        """Sort rows by serialized content and materialize valid per-row orders."""
        row_order = sorted(
            range(len(serialized)),
            key=lambda row: (serialized[row], row),
        )
        values = np.empty(source.shape, dtype=object)
        public_orders = []
        for output_row, source_row in enumerate(row_order):
            values[output_row, :] = [source[source_row, col] for col in order]
            public_orders.append([df.columns[col] for col in order])

        return (
            pd.DataFrame(
                values,
                index=df.index.take(row_order),
                columns=list(df.columns),
            ),
            public_orders,
        )

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Evaluate bounded block candidates, refine one incumbent, and return it."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        rows, width = df.shape
        if rows == 0 or width == 0:
            result = df.copy()
            orders = [[] for _ in range(rows)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((rows, width), dtype=object)
        for col in range(width):
            text[:, col] = [
                self._cell_string(value) for value in source[:, col]
            ]

        columns = list(df.columns)
        stats = self._stats(text)
        blocks = self._blocks(width, columns, col_merge)

        baseline = [
            col
            for col, _ in sorted(
                enumerate(stats),
                key=lambda item: (
                    -item[1][0],
                    -item[1][1],
                    -item[1][2],
                    item[0],
                ),
            )
        ]

        preferences = [baseline] + self._beam_orders(text, stats, blocks)
        best_score = -1
        best_order = None
        best_serialized = None

        for preference in preferences[:3]:
            order = self._repair(
                width, preference, columns, one_way_dep, blocks
            )
            serialized = self._serialize(text, order)
            score = self._score(serialized)
            if score > best_score:
                best_score = score
                best_order = order
                best_serialized = serialized

        best_order, best_serialized, best_score = self._refine_reversals(
            text,
            stats,
            blocks,
            columns,
            one_way_dep,
            best_order,
            best_serialized,
            best_score,
        )

        result, public_orders = self._materialize(
            df, source, best_order, best_serialized
        )
        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

